  "strict-spec-driven/schemas/delta-spec.yaml": `schema: strict-spec-driven/schema/v1
schema_version: 1
schema_id: strict-spec-driven/delta-spec/v1
artifact_type: delta_spec
artifact_name: delta-spec
description: Strict YAML delta spec artifact.
example_ref: ../examples/delta-spec.yaml
coverage_examples:
  - ../examples/delta-spec.operations.yaml
merge_rules:
  exclusive_active_target: |
    A requirement ID that appears as a MODIFIED or REMOVED target in one active change
    MUST NOT appear as a MODIFIED or REMOVED target in any other active change.
    Verify must enforce this constraint and report it as a deterministic validation failure.
  modified_missing_target: |
    If a MODIFIED entry targets a requirement ID that does not exist in the main spec at
    archive time, the entry is treated as ADDED and recorded in the archive merge report.
  removed_missing_target: |
    If a REMOVED entry targets a requirement ID that does not exist in the main spec at
    archive time, the entry is silently skipped and recorded as a skipped removal in the
    archive merge report.
json_schema:
  $schema: "http://json-schema.org/draft-07/schema#"
  definitions:
    step:
      type: object
      properties:
        GIVEN: { type: string }
        WHEN: { type: string }
        THEN: { type: string }
        AND: { type: string }
      additionalProperties: false
      minProperties: 1
      maxProperties: 1
    requirement_value:
      type: object
      additionalProperties: false
      required:
        - strength
        - statement
        - scenarios
      properties:
        strength:
          type: string
          enum:
            - MUST
            - SHOULD
            - MAY
        statement:
          type: string
        scenarios:
          type: object
          additionalProperties:
            type: array
            items:
              "$ref": "#/definitions/step"
            minItems: 1
  type: object
  additionalProperties: false
  required:
    - schema
    - schema_version
    - artifact_type
    - schema_file
    - target_spec
    - mapping
    - operations
  properties:
    schema:
      type: string
      const: strict-spec-driven/delta-spec/v1
    schema_version:
      type: integer
      const: 1
    artifact_type:
      type: string
      const: delta_spec
    schema_file:
      type: string
    target_spec:
      type: string
    mapping:
      type: object
      additionalProperties: false
      required:
        - implementation
        - tests
      properties:
        implementation:
          type: array
          items:
            type: string
        tests:
          type: array
          items:
            type: string
    operations:
      type: object
      additionalProperties: false
      required:
        - ADDED
        - MODIFIED
        - REMOVED
      properties:
        ADDED:
          type: object
          additionalProperties:
            "$ref": "#/definitions/requirement_value"
        MODIFIED:
          type: object
          additionalProperties:
            "$ref": "#/definitions/requirement_value"
        REMOVED:
          type: object
          additionalProperties:
            type: object
            additionalProperties: false
            required:
              - reason
            properties:
              reason:
                type: string
`,
